        elif func_name == 'max':
            if isinstance(self.input_data, list) and self.input_data:
                yield max(self.input_data)
            else:
                yield None

        elif func_name in ['arrays', 'objects', 'iterables', 'booleans', 'numbers', 'strings', 'nulls', 'values', 'scalars']:
            type_checks = {
                'arrays': lambda x: isinstance(x, list),
                'objects': lambda x: isinstance(x, dict),
                'iterables': lambda x: isinstance(x, (list, dict)),
                'booleans': lambda x: isinstance(x, bool),
                'numbers': lambda x: isinstance(x, (int, float)) and not isinstance(x, bool),
                'strings': lambda x: isinstance(x, str),
                'nulls': lambda x: x is None,
                'values': lambda x: x is not None,
                'scalars': lambda x: not isinstance(x, (list, dict)),
            }

            if func_name in type_checks and type_checks[func_name](self.input_data):
                yield self.input_data

        elif func_name == 'first':
            if isinstance(self.input_data, list) and self.input_data:
                yield self.input_data[0]
