                    start = arg_values[0]
                    end = arg_values[1]
                    if len(arg_values) >= 3:
                        step = arg_values[2]

                if end is not None:
                    i = start
                    if step > 0:
                        while i < end:
                            yield i
                            i += step
                    else:
