    while (input[*pos] && input[*pos] != '"') {
        if (input[*pos] == '\\') {
            (*pos)++;
            switch (input[*pos]) {
                case 'n': buffer[i++] = '\n'; break;
                case 't': buffer[i++] = '\t'; break;
                case 'r': buffer[i++] = '\r'; break;
                case '"': buffer[i++] = '"'; break;
                case '\\': buffer[i++] = '\\'; break;
                case '/': buffer[i++] = '/'; break;
                case 'b': buffer[i++] = '\b'; break;
                case 'f': buffer[i++] = '\f'; break;
                default:
                    buffer[i++] = input[*pos];
            }
        } else {
            buffer[i++] = input[*pos];
        }
        (*pos)++;
    }
    buffer[i] = '\0';
    (*pos)++; // Skip closing quote

    return json_string(buffer);
}

json_value *parse_number(const char *input, size_t *pos) {
    char buffer[100];
    size_t i = 0;

    if (input[*pos] == '-') buffer[i++] = input[(*pos)++];

    while (input[*pos] && (isdigit(input[*pos]) || input[*pos] == '.' || 
                          input[*pos] == 'e' || input[*pos] == 'E' ||
                          input[*pos] == '+' || input[*pos] == '-')) {
        buffer[i++] = input[(*pos)++];
