        {"version", no_argument, &show_version, 1},
        {"help", no_argument, &show_help, 1},
        {0, 0, 0, 0}
    };

    int option_index = 0;
    int c;

    while ((c = getopt_long(argc, argv, "nRscrajSMeVh", long_options, &option_index)) != -1) {
        switch (c) {
            case 'n': opts.null_input = 1; break;
            case 'R': opts.raw_input = 1; break;
            case 's': opts.slurp = 1; break;
            case 'c': opts.compact_output = 1; break;
