        json_value *output = apply_filter(input, filter);
        json_print(output, opts.compact_output, opts.sort_keys);
        printf("\n");
        json_free(input);
        json_free(output);
    } else {
        while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
            bytes += strlen(buffer);
            if (bytes >= sizeof(buffer)) {
                fprintf(stderr, "Input too large\n");
                return 1;
            }
        }

        if (bytes == 0 || !isatty(STDIN_FILENO)) {
            // Data available - parse it
            size_t pos = 0;
            json_value *input = json_parse(buffer, &pos);
            if (input) {
                json_value *output = apply_filter(input, filter);
                json_print(output, opts.compact_output, opts.sort_keys);
                printf("\n");
                json_free(input);
                json_free(output);
            } else {
                fprintf(stderr, "Parse error\n");
                return 1;
            }
        }
    }

    return 0;
}
