                }
                json_value *key_val = parse_string(input, pos);

                skip_whitespace(input, pos);
                if (input[*pos] != ':') {
                    fprintf(stderr, "Expected ':'\n");
                    json_free(obj);
                    json_free(key_val);
                    return NULL;
