        json_value *arr = json_array();
        skip_whitespace(input, pos);

        if (input[*pos] != ']') {
            while (1) {
                json_value *val = json_parse(input, pos);
                json_array_append(arr, val);

                skip_whitespace(input, pos);
                if (input[*pos] == ']') {
