void json_print_indent(json_value *val, int indent_level, int compact, int sort_keys) {
    if (!val) return;

    switch (val->type) {
        case JSON_NULL:
            printf("null");
            break;
        case JSON_BOOL:
            printf("%s", val->data.bool_val ? "true" : "false");
            break;
        case JSON_NUMBER: {
            double n = val->data.number_val;
            if (n == (long long)n) {
                printf("%lld", (long long)n);
            } else {
                printf("%g", n);
            }
            break;
        }
        case JSON_STRING: {
            printf("\"");
            for (const char *p = val->data.string_val; *p; p++) {
                switch (*p) {
                    case '"': printf("\\\""); break;
                    case '\\': printf("\\\\"); break;
                    case '\n': printf("\\n"); break;
                    case '\t': printf("\\t"); break;
                    case '\r': printf("\\r"); break;
                    case '\b': printf("\\b"); break;
                    case '\f': printf("\\f"); break;
                    default:
                        if (*p < 32) {
                            printf("\\u%04x", *p);
                        } else {
                            printf("%c", *p);
                        }
                }
            }
            printf("\"");
            break;
        }
        case JSON_ARRAY:
            printf("[");
            if (!compact && val->data.array_val.count > 0) {
                printf("\n");
            }
            for (size_t i = 0; i < val->data.array_val.count; i++) {
                if (!compact) {
                    for (int j = 0; j < indent_level + 1; j++) printf("  ");
                }
                json_print_indent(val->data.array_val.items[i], indent_level + 1, compact, sort_keys);
                if (i < val->data.array_val.count - 1) {
                    printf(",");
                }
                if (!compact) {
                    printf("\n");
                }
            }
            if (!compact && val->data.array_val.count > 0) {
                for (int j = 0; j < indent_level; j++) printf("  ");
            }
            printf("]");
            break;
        case JSON_OBJECT: {
            printf("{");
            if (!compact && val->data.object_val.count > 0) {
                printf("\n");
            }
            for (size_t i = 0; i < val->data.object_val.count; i++) {
                if (!compact) {
                    for (int j = 0; j < indent_level + 1; j++) printf("  ");
                }
                printf("\"%s\":", val->data.object_val.pairs[i].key);
                if (!compact) printf(" ");
                json_print_indent(val->data.object_val.pairs[i].value, indent_level + 1, compact, sort_keys);
                if (i < val->data.object_val.count - 1) {
                    printf(",");
                }
                if (!compact) {
                    printf("\n");
                }
            }
            if (!compact && val->data.object_val.count > 0) {
                for (int j = 0; j < indent_level; j++) printf("  ");
            }
            printf("}");
            break;
        }
    }
}

