                escape_char = self.consume()
                if escape_char == 'n':
                    chars.append('\n')
                elif escape_char == 't':
                    chars.append('\t')
                elif escape_char == 'r':
                    chars.append('\r')
                elif escape_char == '"':
                    chars.append('"')
                elif escape_char == '\\':
                    chars.append('\\')
                elif escape_char == '/':
                    chars.append('/')
                elif escape_char == 'b':
                    chars.append('\b')
                elif escape_char == 'f':
                    chars.append('\f')
