                    break

        elif func_name == 'contains':
            if args:
                for needle in self.eval(args[0]):
                    if isinstance(self.input_data, str) and isinstance(needle, str):
                        yield needle in self.input_data
                    elif isinstance(self.input_data, list):
                        yield needle in self.input_data
                    elif isinstance(self.input_data, dict) and isinstance(needle, dict):
                        yield all(k in self.input_data and self.input_data[k] == v for k, v in needle.items())
                    else:
                        yield False
                    break

        elif func_name == 'inside':
            if args:
                for haystack in self.eval(args[0]):
                    if isinstance(haystack, str) and isinstance(self.input_data, str):
                        yield self.input_data in haystack
                    elif isinstance(haystack, list):
                        yield self.input_data in haystack
                    elif isinstance(haystack, dict) and isinstance(self.input_data, dict):
                        yield all(k in haystack and haystack[k] == v for k, v in self.input_data.items())
                    else:
                        yield False
                    break

        elif func_name == 'startswith':
            if args:
                for prefix in self.eval(args[0]):
                    if isinstance(self.input_data, str) and isinstance(prefix, str):
