        print('  -r, --raw-output          output strings without escapes and quotes;')
        print('      --raw-output0         implies -r and output NUL after each output;')
        print('  -j, --join-output         implies -r and output without newline after')
        print('                            each output;')
        print('  -a, --ascii-output        output strings by only ASCII characters')
        print('                            using escape sequences;')
        print('  -S, --sort-keys           sort keys of each object on output;')
        print('  -C, --color-output        colorize JSON output;')
        print('  -M, --monochrome-output   disable colored output;')
        print('      --tab                 use tabs for indentation;')
        print('      --indent n            use n spaces for indentation (max 7 spaces);')
        print('      --unbuffered          flush output stream after each output;')
        print('      --stream              parse the input value in streaming fashion;')
        print('      --stream-errors       implies --stream and report parse error as')
        print('                            an array;')
        print('      --seq                 parse input/output as application/json-seq;')
        print('  -f, --from-file           load the filter from a file;')
        print('  -L, --library-path dir    search modules from the directory;')
        print('      --arg name value      set $name to the string value;')
        print('      --argjson name value  set $name to the JSON value;')
        print('      --slurpfile name file set $name to an array of JSON values read')
        print('                            from the file;')
        print('      --rawfile name file   set $name to string contents of file;')
        print('      --args                consume remaining arguments as positional')
        print('                            string values;')
        print('      --jsonargs            consume remaining arguments as positional')
        print('                            JSON values;')
        print('  -e, --exit-status         set exit status code based on the output;')
        print('  -V, --version             show the version;')
        print('  --build-configuration     show jq\'s build configuration;')
        print('  -h, --help                show the help;')
        print('  --                        terminates argument processing;')
        print()
        print('Named arguments are also available as $ARGS.named[], while')
        print('positional arguments are available as $ARGS.positional[].')
        sys.exit(0)

    # Get filter
    if args.from_file:
        with open(args.from_file, 'r') as f:
            filter_str = f.read()
    elif args.filter:
        filter_str = args.filter
    else:
        print('jq: filter required', file=sys.stderr)
        sys.exit(1)

    # Create processor
    processor = JQProcessor(
        null_input=args.null_input,
        raw_input=args.raw_input,
        slurp=args.slurp,
        compact_output=args.compact_output,
        raw_output=args.raw_output or args.raw_output0 or args.join_output,
        raw_output0=args.raw_output0,
        join_output=args.join_output,
        sort_keys=args.sort_keys,
        ascii_output=args.ascii_output,
        tab=args.tab,
        indent=args.indent,
        exit_status=args.exit_status,
        color_output=args.color_output,
        monochrome_output=args.monochrome_output
    )

    try:
        # Get inputs
        if args.null_input:
            inputs = [None]
        else:
            inputs = list(processor.read_inputs(args.files if args.files else ['-']))

        # Process each input
        has_output = False
        for input_data in inputs:
            try:
                for output in processor.process_filter(filter_str, input_data):
                    has_output = True
                    output_str = processor.output_value(output)

                    if args.raw_output0:
                        sys.stdout.write(output_str)
                        sys.stdout.write('\0')
                    elif args.join_output:
                        sys.stdout.write(output_str)
                    else:
                        print(output_str)
            except Exception as e:
                print(f'jq: error: {e}', file=sys.stderr)
                sys.exit(1)

        if args.exit_status:
            sys.exit(0 if has_output else 1)

    except Exception as e:
        print(f'jq: error: {e}', file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()
