        return left

    def parse_alternative(self):
        """Parse alternative operator //"""
        left = self.parse_comparison()

        while True:
            self.skip_whitespace()
            if self.peek() == '/' and self.peek(1) == '/':
                self.consume('/')
                self.consume('/')
                right = self.parse_comparison()
                left = ('alternative', left, right)
            else:
                break

        return left

    def parse_comparison(self):
        """Parse comparison operators"""
        left = self.parse_additive()

        self.skip_whitespace()
        if self.pos < len(self.filter_str):
            if self.pos + 1 < len(self.filter_str) and \
               self.filter_str[self.pos:self.pos+2] in ['==', '!=', '<=', '>=']:
                op = self.filter_str[self.pos:self.pos+2]
                self.pos += 2
                right = self.parse_additive()
                left = ('compare', op, left, right)
            elif self.peek() in '<>':
                op = self.consume()
                right = self.parse_additive()
                left = ('compare', op, left, right)

        return left

    def parse_additive(self):
        """Parse addition and subtraction"""
        left = self.parse_multiplicative()

        while True:
            self.skip_whitespace()
            if self.peek() in ['+', '-']:
                op = self.consume()
                right = self.parse_multiplicative()
                left = ('arith', op, left, right)
            else:
                break

        return left

    def parse_multiplicative(self):
        """Parse multiplication, division, modulo"""
        left = self.parse_postfix()

        while True:
            self.skip_whitespace()
            if self.peek() in ['*', '/', '%']:
                op = self.consume()
                right = self.parse_postfix()
                left = ('arith', op, left, right)
            else:
                break

        return left

    def parse_postfix(self):
        """Parse postfix expressions (field access, array indexing, etc)"""
        expr = self.parse_primary()

        while True:
            self.skip_whitespace()
            if self.peek() == '.':
                self.consume('.')
                if self.peek() == '[':
                    # .[expr]
                    self.consume('[')
                    if self.peek() == ']':
                        self.consume(']')
                        expr = ('iterate', expr)
                    else:
                        index_expr = self.parse_pipe()
                        self.skip_whitespace()
                        self.consume(']')
                        expr = ('index', expr, index_expr)
                elif self.peek() == '"':
                    # ."field"
                    field = self.parse_string()
                    expr = ('field', expr, ('literal', field))
                elif self.peek() == '.':
                    # .. (recursion)
                    self.consume('.')
                    expr = ('recurse', expr)
                elif self.peek() and (self.peek().isalpha() or self.peek() == '_'):
                    # .field
                    field = self.parse_identifier()
                    expr = ('field', expr, ('literal', field))
                elif self.peek() in ['[', '{', '(', None, ' ', '\t', '\n', '|', ')', ',', ';', '?']:
                    # Just a dot, return as is
                    expr = ('field', expr, ('literal', None))
                else:
                    break
            elif self.peek() == '[':
                self.consume('[')
                if self.peek() == ']':
                    # .[]
                    self.consume(']')
                    expr = ('iterate', expr)
                else:
                    # .[expr]
                    index_expr = self.parse_pipe()
                    self.skip_whitespace()
                    self.consume(']')
                    expr = ('index', expr, index_expr)
            elif self.peek() == '?':
                # Try operator
                self.consume('?')
                expr = ('try', expr)
            else:
                break

        return expr

    def parse_primary(self):
        """Parse primary expressions"""
        self.skip_whitespace()

        if self.peek() is None:
            raise ValueError("Unexpected end of input")

        # Identity
        if self.peek() == '.':
            self.consume('.')
            if self.peek() == '[':
                # .[...]
                self.consume('[')
                if self.peek() == ']':
                    self.consume(']')
                    return ('iterate', ('identity',))
                else:
                    index_expr = self.parse_pipe()
                    self.skip_whitespace()
                    self.consume(']')
                    return ('index', ('identity',), index_expr)
            elif self.peek() == '.':
                # .. recursion from root
                self.consume('.')
                return ('recurse', ('identity',))
            elif self.peek() and (self.peek().isalpha() or self.peek() == '_' or self.peek() == '"'):
                # Field access
                if self.peek() == '"':
                    field = self.parse_string()
                else:
                    field = self.parse_identifier()
                return ('field', ('identity',), ('literal', field))
            else:
                return ('identity',)

        # String
        if self.peek() == '"':
            return ('literal', self.parse_string())

        # Number
        if self.peek() == '-' or (self.peek() and self.peek().isdigit()):
            return ('literal', self.parse_number())

        # Array literal
        if self.peek() == '[':
            return self.parse_array_constructor()

        # Object literal
        if self.peek() == '{':
            return self.parse_object_constructor()

        # Parentheses
        if self.peek() == '(':
            self.consume('(')
            expr = self.parse_pipe()
            self.skip_whitespace()
            self.consume(')')
            return expr

        # Keywords and identifiers
        if self.peek() and (self.peek().isalpha() or self.peek() == '_'):
            keyword = self.parse_identifier()

            # Keywords
            if keyword == 'if':
                return self.parse_if()
            elif keyword == 'null':
                return ('literal', None)
            elif keyword == 'true':
                return ('literal', True)
            elif keyword == 'false':
                return ('literal', False)
            elif keyword in ['map', 'select', 'empty', 'error', 'add', 'length', 
                           'keys', 'keys_unsorted', 'values', 'type', 'reverse', 
                           'sort', 'group_by', 'unique', 'unique_by', 'max', 'min',
                           'max_by', 'min_by', 'flatten', 'range', 'floor', 'sqrt',
                           'tonumber', 'tostring', 'arrays', 'objects', 'iterables',
                           'booleans', 'numbers', 'strings', 'nulls', 'values',
                           'scalars', 'first', 'last', 'nth', 'indices', 'index',
                           'rindex', 'inside', 'contains', 'startswith', 'endswith',
                           'ltrimstr', 'rtrimstr', 'split', 'join', 'ascii_downcase',
                           'ascii_upcase', 'tojsonstream', 'fromjson', 'tojson',
                           'has', 'in', 'del', 'with_entries', 'from_entries',
                           'paths', 'leaf_paths', 'any', 'all', 'recurse_down',
                           'walk', 'transpose', 'combinations', 'ascii', 'implode',
                           'explode', 'ltrimstr', 'rtrimstr', 'inside', 'getpath',
                           'setpath', 'delpaths']:
                # Built-in functions
                if self.peek() == '(':
                    self.consume('(')
                    args = []
                    if self.peek() != ')':
                        args.append(self.parse_pipe())
                        while self.peek() == ';':
                            self.consume(';')
                            args.append(self.parse_pipe())
                    self.skip_whitespace()
                    self.consume(')')
                    return ('call', keyword, args)
                else:
                    return ('call', keyword, [])
            elif keyword == 'empty':
                return ('empty',)
            else:
                # Variable reference or function call
                if self.peek() == '(':
                    self.consume('(')
                    args = []
                    if self.peek() != ')':
                        args.append(self.parse_pipe())
                        while self.peek() == ';':
                            self.consume(';')
                            args.append(self.parse_pipe())
                    self.skip_whitespace()
                    self.consume(')')
                    return ('call', keyword, args)
                else:
                    return ('variable', keyword)

        raise ValueError(f"Unexpected character: {self.peek()}")

    def parse_if(self):
        """Parse if-then-else expressions"""
        # 'if' already consumed
        condition = self.parse_pipe()
        self.skip_whitespace()
        self.consume_keyword('then')
        then_expr = self.parse_pipe()

        self.skip_whitespace()
        elif_parts = []
        while self.match_keyword('elif'):
            self.consume_keyword('elif')
            elif_cond = self.parse_pipe()
            self.skip_whitespace()
            self.consume_keyword('then')
            elif_then = self.parse_pipe()
            elif_parts.append((elif_cond, elif_then))
            self.skip_whitespace()

        else_expr = None
        if self.match_keyword('else'):
            self.consume_keyword('else')
            else_expr = self.parse_pipe()

        self.skip_whitespace()
        self.consume_keyword('end')

        if elif_parts:
            elif_node = ('if', elif_parts[0][0], elif_parts[0][1], 
                        ('if', elif_parts[1][0], elif_parts[1][1], else_expr) if len(elif_parts) > 1 else else_expr)
            return ('if', condition, then_expr, elif_node)
        else:
            return ('if', condition, then_expr, else_expr)

    def parse_array_constructor(self):
        """Parse array literal [...]"""
        self.consume('[')
        self.skip_whitespace()

        if self.peek() == ']':
            self.consume(']')
            return ('array', [])

        exprs = [self.parse_pipe()]
        while True:
            self.skip_whitespace()
            if self.peek() == ',':
                self.consume(',')
                exprs.append(self.parse_pipe())
            else:
                break

        self.skip_whitespace()
        self.consume(']')
        return ('array', exprs)

    def parse_object_constructor(self):
        """Parse object literal {...}"""
        self.consume('{')
        self.skip_whitespace()

        pairs = []
        if self.peek() != '}':
            # Parse key-value pairs
            while True:
                self.skip_whitespace()

                # Parse key
                if self.peek() == '"':
                    key = ('literal', self.parse_string())
                elif self.peek() == '(':
                    self.consume('(')
                    key = self.parse_pipe()
                    self.skip_whitespace()
                    self.consume(')')
                elif self.peek() and (self.peek().isalpha() or self.peek() == '_'):
                    key_str = self.parse_identifier()
                    key = ('literal', key_str)
                else:
                    raise ValueError(f"Unexpected character in object key: {self.peek()}")

                self.skip_whitespace()
                if self.peek() != ':':
                    raise ValueError(f"Expected ':', got {self.peek()}")
                self.consume(':')

                # Parse value
                value = self.parse_pipe()
                pairs.append((key, value))

                self.skip_whitespace()
                if self.peek() == ',':
                    self.consume(',')
                elif self.peek() == '}':
                    break
                else:
                    raise ValueError(f"Expected ',' or '}}', got {self.peek()}")

        self.skip_whitespace()
        self.consume('}')
        return ('object', pairs)

    def parse_string(self):
        """Parse a JSON string"""
        self.consume('"')
        chars = []
        while self.peek() != '"':
            if self.peek() == '\\':
                self.consume('\\')
                escape_char = self.consume()
                if escape_char == 'n':
                    chars.append('\n')
                elif escape_char == 't':
                    chars.append('\t')
                elif escape_char == 'r':
                    chars.append('\r')
                elif escape_char == '"':
                    chars.append('"')
                elif escape_char == '\\':
                    chars.append('\\')
                elif escape_char == '/':
                    chars.append('/')
                elif escape_char == 'b':
                    chars.append('\b')
                elif escape_char == 'f':
                    chars.append('\f')
                elif escape_char == 'u':
                    hex_chars = ''
                    for _ in range(4):
                        hex_chars += self.consume()
                    chars.append(chr(int(hex_chars, 16)))
                else:
                    chars.append(escape_char)
            else:
                chars.append(self.consume())
        self.consume('"')
        return ''.join(chars)

    def parse_number(self):
        """Parse a JSON number"""
        num_str = ''
        if self.peek() == '-':
            num_str += self.consume('-')

        while self.peek() and (self.peek().isdigit() or self.peek() in '.eE+-'):
            num_str += self.consume()

        if '.' in num_str or 'e' in num_str or 'E' in num_str:
            return float(num_str)
        else:
            return int(num_str)

    def parse_identifier(self):
        """Parse an identifier"""
        chars = []
        while self.peek() and (self.peek().isalnum() or self.peek() == '_'):
            chars.append(self.consume())
        return ''.join(chars)

    def match_keyword(self, keyword):
        """Check if next token is a keyword"""
        saved_pos = self.pos
        self.skip_whitespace()
        match = True
        for char in keyword:
            if self.peek() != char:
                match = False
                break
            self.consume()
        # Check that keyword is not followed by alphanumeric
        if match and self.peek() and (self.peek().isalnum() or self.peek() == '_'):
            match = False
        self.pos = saved_pos
        return match

    def consume_keyword(self, keyword):
        """Consume a keyword"""
        self.skip_whitespace()
        for char in keyword:
            self.consume(char)


class FilterEvaluator:
    """Evaluate jq filter AST"""

    def __init__(self, input_data):
        self.input_data = input_data
        self.variables = {}

    def eval(self, ast) -> Iterator[Any]:
        """Evaluate AST and yield results"""
        if ast[0] == 'identity':
            yield self.input_data

        elif ast[0] == 'literal':
            yield ast[1]

        elif ast[0] == 'pipe':
            # Pass output of left as input to right
            left_ast = ast[1]
            right_ast = ast[2]
            for value in self.eval(left_ast):
                # Create new evaluator with piped value
                right_eval = FilterEvaluator(value)
                right_eval.variables = self.variables.copy()
                yield from right_eval.eval(right_ast)

        elif ast[0] == 'comma':
            # Generate multiple outputs
            for expr in ast[1]:
                yield from self.eval(expr)

        elif ast[0] == 'field':
            expr_ast = ast[1]
            field_ast = ast[2]
            for value in self.eval(expr_ast):
                if field_ast[0] == 'literal':
                    field_name = field_ast[1]
                    if field_name is None:
                        # Just . on a value
                        yield value
                    elif isinstance(value, dict):
                        if field_name in value:
                            yield value[field_name]
                        else:
                            yield None
                    else:
                        yield None

        elif ast[0] == 'index':
            expr_ast = ast[1]
            index_ast = ast[2]
            for value in self.eval(expr_ast):
                for index in self.eval(index_ast):
                    # Properly evaluate index
                    if isinstance(value, dict):
                        if isinstance(index, str):
                            yield value.get(index, None)
                        else:
                            yield None
                    elif isinstance(value, list):
                        if isinstance(index, int):
                            try:
                                if index < 0:
                                    yield value[index]
                                else:
                                    yield value[index]
                            except IndexError:
                                yield None
                        elif isinstance(index, str):
                            # Slicing support
                            if ':' in index:
                                parts = index.split(':')
                                start = int(parts[0]) if parts[0] else None
                                end = int(parts[1]) if len(parts) > 1 and parts[1] else None
                                yield value[start:end]
                            else:
                                yield None
                        else:
                            yield None
                    elif value is None:
                        yield None
                    elif isinstance(value, str) and isinstance(index, int):
                        try:
                            yield value[index]
                        except IndexError:
                            yield None

        elif ast[0] == 'iterate':
            expr_ast = ast[1]
            for value in self.eval(expr_ast):
                if isinstance(value, list):
                    for item in value:
                        yield item
                elif isinstance(value, dict):
                    for v in value.values():
                        yield v
                else:
                    yield value

        elif ast[0] == 'array':
            items = []
            for expr in ast[1]:
                for value in self.eval(expr):
                    items.append(value)
            yield items

        elif ast[0] == 'object':
            obj = {}
            for key_ast, value_ast in ast[1]:
                for key in self.eval(key_ast):
                    for value in self.eval(value_ast):
                        key_str = str(key) if not isinstance(key, str) else key
                        obj[key_str] = value
                        break  # Only take first value
                    break  # Only take first key
            yield obj

        elif ast[0] == 'if':
            condition_ast = ast[1]
            then_ast = ast[2]
            else_ast = ast[3]

            for cond_value in self.eval(condition_ast):
                if self.is_truthy(cond_value):
                    yield from self.eval(then_ast)
                else:
                    if else_ast:
                        yield from self.eval(else_ast)

        elif ast[0] == 'compare':
            op = ast[1]
            left_ast = ast[2]
            right_ast = ast[3]

            for left in self.eval(left_ast):
                for right in self.eval(right_ast):
                    if op == '==':
                        yield left == right
                    elif op == '!=':
                        yield left != right
                    elif op == '<':
                        yield left < right
                    elif op == '>':
                        yield left > right
                    elif op == '<=':
                        yield left <= right
                    elif op == '>=':
                        yield left >= right

        elif ast[0] == 'arith':
            op = ast[1]
            left_ast = ast[2]
            right_ast = ast[3]

            for left in self.eval(left_ast):
                for right in self.eval(right_ast):
                    if op == '+':
                        if isinstance(left, str) or isinstance(right, str):
                            yield str(left) + str(right)
                        elif isinstance(left, list) and isinstance(right, list):
                            yield left + right
                        elif isinstance(left, dict) and isinstance(right, dict):
                            result = left.copy()
                            result.update(right)
                            yield result
                        else:
                            yield left + right
                    elif op == '-':
                        if isinstance(left, list) and isinstance(right, list):
                            result = left.copy()
                            for item in right:
                                if item in result:
                                    result.remove(item)
                            yield result
                        else:
                            yield left - right
                    elif op == '*':
                        if isinstance(left, str) and isinstance(right, int):
                            yield left * right
                        elif isinstance(left, int) and isinstance(right, str):
                            yield right * left
                        elif isinstance(left, list) and isinstance(right, int):
                            yield left * right
                        elif isinstance(left, int) and isinstance(right, list):
                            yield right * left
                        elif isinstance(left, dict) and isinstance(right, dict):
                            # Merge objects
                            result = {}
                            for k in left:
                                if k in right:
                                    result[k] = right[k]
                            yield result
                        else:
                            yield left * right
                    elif op == '/':
                        if isinstance(left, str) and isinstance(right, str):
                            yield left.split(right)
                        else:
                            yield left / right
                    elif op == '%':
                        yield left % right

        elif ast[0] == 'alternative':
            left_ast = ast[1]
            right_ast = ast[2]

            found = False
            for value in self.eval(left_ast):
                if value is not None and value is not False:
                    yield value
                    found = True

            if not found:
                yield from self.eval(right_ast)

        elif ast[0] == 'call':
            func_name = ast[1]
            args = ast[2] if len(ast) > 2 else []
            yield from self.eval_function(func_name, args)

        elif ast[0] == 'try':
            expr_ast = ast[1]
            try:
                yield from self.eval(expr_ast)
            except:
                pass

        elif ast[0] == 'empty':
            return
            # Yield nothing

        elif ast[0] == 'recurse':
            expr_ast = ast[1]
            def recurse_values(val):
                yield val
                if isinstance(val, dict):
                    for v in val.values():
                        yield from recurse_values(v)
                elif isinstance(val, list):
                    for v in val:
                        yield from recurse_values(v)

            for value in self.eval(expr_ast):
                yield from recurse_values(value)

        else:
            raise ValueError(f"Unknown AST node: {ast[0]}")

    def eval_function(self, func_name: str, args: List) -> Iterator[Any]:
        """Evaluate built-in functions"""

        if func_name == 'map':
            if not isinstance(self.input_data, list):
                raise ValueError("map can only be used on arrays")

            result = []
            for item in self.input_data:
                evaluator = FilterEvaluator(item)
                evaluator.variables = self.variables.copy()
                for value in evaluator.eval(args[0]):
                    result.append(value)
                    break  # Only take first result
            yield result

        elif func_name == 'select':
            if not args:
                raise ValueError("select requires a condition")

            for value in self.eval(args[0]):
                if self.is_truthy(value):
                    yield self.input_data
                    break

        elif func_name == 'empty':
            return

        elif func_name == 'add':
            if isinstance(self.input_data, list):
                if not self.input_data:
                    yield None
                else:
                    result = self.input_data[0]
                    for item in self.input_data[1:]:
                        if isinstance(result, str) or isinstance(item, str):
                            result = str(result) + str(item)
                        elif isinstance(result, list):
                            result = result + item
                        elif isinstance(result, dict):
                            result = {**result, **item}
                        else:
                            result = result + item
                    yield result
            else:
                yield self.input_data

        elif func_name == 'length':
            if self.input_data is None:
                yield 0
            elif isinstance(self.input_data, (str, list, dict)):
                yield len(self.input_data)
            elif isinstance(self.input_data, (int, float)):
                yield abs(self.input_data)
            else:
                yield None

        elif func_name == 'keys':
            if isinstance(self.input_data, dict):
                yield sorted(self.input_data.keys())
            elif isinstance(self.input_data, list):
                yield list(range(len(self.input_data)))
            else:
                yield None

        elif func_name == 'keys_unsorted':
            if isinstance(self.input_data, dict):
                yield list(self.input_data.keys())
            elif isinstance(self.input_data, list):
                yield list(range(len(self.input_data)))
            else:
                yield None

        elif func_name == 'values':
            if isinstance(self.input_data, dict):
                for v in self.input_data.values():
                    yield v
            elif isinstance(self.input_data, list):
                for v in self.input_data:
                    yield v
            else:
                yield self.input_data

        elif func_name == 'type':
            if self.input_data is None:
                yield 'null'
            elif isinstance(self.input_data, bool):
                yield 'boolean'
            elif isinstance(self.input_data, int):
                yield 'number'
            elif isinstance(self.input_data, float):
                yield 'number'
            elif isinstance(self.input_data, str):
                yield 'string'
            elif isinstance(self.input_data, list):
                yield 'array'
            elif isinstance(self.input_data, dict):
                yield 'object'
            else:
                yield 'unknown'

        elif func_name == 'reverse':
            if isinstance(self.input_data, list):
                yield list(reversed(self.input_data))
            else:
                yield self.input_data

        elif func_name == 'sort':
            if isinstance(self.input_data, list):
                try:
                    yield sorted(self.input_data)
                except TypeError:
                    yield self.input_data
            else:
                yield self.input_data

        elif func_name == 'unique':
            if isinstance(self.input_data, list):
                seen = set()
                result = []
                for item in self.input_data:
                    if isinstance(item, (list, dict)):
                        item_key = json.dumps(item, sort_keys=True)
                    else:
                        item_key = item
                    if item_key not in seen:
                        seen.add(item_key)
                        result.append(item)
                yield sorted(result) if isinstance(result[0] if result else None, (int, str)) else result
            else:
                yield self.input_data

        elif func_name == 'flatten':
            depth = 1
            if args:
                for d in self.eval(args[0]):
                    depth = int(d)
                    break

            def flatten_list(lst, d):
                if d == 0:
                    return lst
                result = []
                for item in lst:
                    if isinstance(item, list):
                        result.extend(flatten_list(item, d - 1))
                    else:
                        result.append(item)
                return result

            if isinstance(self.input_data, list):
                yield flatten_list(self.input_data, depth)
            else:
                yield self.input_data

        elif func_name == 'group_by':
            if not args or not isinstance(self.input_data, list):
                yield self.input_data
            else:
                groups = {}
                for item in self.input_data:
                    evaluator = FilterEvaluator(item)
                    evaluator.variables = self.variables.copy()
                    for key in evaluator.eval(args[0]):
                        key_str = json.dumps(key, sort_keys=True)
                        if key_str not in groups:
                            groups[key_str] = []
                        groups[key_str].append(item)
                        break

                yield list(groups.values())

        elif func_name == 'min':
