                    break

        elif func_name == 'ltrimstr':
            if args:
                for prefix in self.eval(args[0]):
                    if isinstance(self.input_data, str) and isinstance(prefix, str):
                        if self.input_data.startswith(prefix):
                            yield self.input_data[len(prefix):]
                        else:
                            yield self.input_data
                    else:
                        yield self.input_data
                    break

        elif func_name == 'rtrimstr':
            if args:
                for suffix in self.eval(args[0]):
                    if isinstance(self.input_data, str) and isinstance(suffix, str):
                        if self.input_data.endswith(suffix):
                            yield self.input_data[:-len(suffix)]
                        else:
                            yield self.input_data
                    else:
                        yield self.input_data
                    break

        elif func_name == 'split':
            if args:
                for sep in self.eval(args[0]):
                    if isinstance(self.input_data, str) and isinstance(sep, str):
                        yield self.input_data.split(sep)
                    else:
                        yield self.input_data
                    break

        elif func_name == 'join':
            if args:
                for sep in self.eval(args[0]):
                    if isinstance(self.input_data, list):
                        yield sep.join(str(x) for x in self.input_data)
                    else:
                        yield self.input_data
                    break

        elif func_name == 'ascii_downcase':
            if isinstance(self.input_data, str):
                yield self.input_data.lower()
            else:
                yield self.input_data

        elif func_name == 'ascii_upcase':
            if isinstance(self.input_data, str):
                yield self.input_data.upper()
            else:
                yield self.input_data

        elif func_name == 'tonumber':
            try:
                if isinstance(self.input_data, str):
                    if '.' in self.input_data or 'e' in self.input_data.lower():
                        yield float(self.input_data)
                    else:
                        yield int(self.input_data)
                else:
                    yield self.input_data
            except ValueError:
                raise ValueError(f"Cannot convert {self.input_data} to number")

        elif func_name == 'tostring':
            if isinstance(self.input_data, str):
                yield self.input_data
            elif self.input_data is None:
                yield 'null'
            elif isinstance(self.input_data, bool):
                yield 'true' if self.input_data else 'false'
            else:
                yield str(self.input_data)

        elif func_name == 'tojson':
            yield json.dumps(self.input_data, separators=(',', ':'))

        elif func_name == 'fromjson':
            if isinstance(self.input_data, str):
                yield json.loads(self.input_data)
            else:
                yield self.input_data

        elif func_name == 'floor':
            import math
            if isinstance(self.input_data, (int, float)):
                yield math.floor(self.input_data)
            else:
                yield self.input_data

        elif func_name == 'sqrt':
            import math
            if isinstance(self.input_data, (int, float)):
                yield math.sqrt(self.input_data)
            else:
                yield self.input_data

        elif func_name == 'range':
            if not args:
