                start = 0
                end = None
                step = 1

                arg_values = []
                for arg in args:
                    for val in self.eval(arg):
                        arg_values.append(int(val))
                        break

                if len(arg_values) == 1:
                    end = arg_values[0]
                elif len(arg_values) >= 2:
                    start = arg_values[0]
                    end = arg_values[1]
                    if len(arg_values) >= 3:
                        step = arg_values[2]

                if end is not None:
                    i = start
                    if step > 0:
