        ascii_output=args.ascii_output,
        tab=args.tab,
        indent=args.indent,
        exit_status=args.exit_status,
        color_output=args.color_output,
        monochrome_output=args.monochrome_output
    )

    try:
        # Get inputs
        if args.null_input:
            inputs = [None]
        else:
            inputs = list(processor.read_inputs(args.files if args.files else ['-']))

        # Process each input
        has_output = False
        for input_data in inputs:
