# Simulate parsing
class P:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def peek(self, offset=0):
        if self.pos + offset < len(self.s):
            return self.s[self.pos + offset]
        return None

    def skip_ws(self):
        while self.pos < len(self.s) and self.s[self.pos].isspace():
            self.pos += 1

    def test(self):
        self.pos = 2  # After 'b'
        self.skip_ws()
        print(f"After skip_ws: pos={self.pos}, peek()='{self.peek()}', peek(1)='{self.peek(1)}'")
        if self.peek() == '/' and self.peek(1) == '/':
            print("Found //"!)
        else:
            print(f"Not found. peek()={repr(self.peek())}, peek(1)={repr(self.peek(1))}")

p = P(test)
p.test()
